/**
 * Wire types and protocol constants shared by the Node half (series/control
 * routes, loop texts) and the browser half (the panel). The continuation
 * message anchors live here because they are a two-sided protocol: `loop.ts`
 * builds continuation/wrap-up texts around them, and `projection.ts` parses
 * the same texts back out of the session log.
 * @module
 */

/** One kernel evaluation (bench call) projected from the session log. */
export interface WireIteration {
  /** Session-log seq of the `tool/call` event (stable identity + ordering). */
  seq: number
  /** Tool name as logged (MCP tools keep their server prefix). */
  tool: string
  /** Evaluator-assigned id (e.g. `"0007"`) when the result carried one. */
  evaluationId?: string
  /** Whether the artifact compiled; absent while pending or unparsable. */
  compiled?: boolean
  /** Evaluator correctness verdict; absent while pending or not measured. */
  correct?: boolean
  /** Wall latency in milliseconds; absent when not measured. */
  latencyMs?: number
  /**
   * Speedup vs the benchmark's reference kernel, taken from the evaluator's
   * own numbers (an explicit `speedup` metric, else `ref_runtime_ms` ÷
   * latency); absent when the evaluator reported neither.
   */
  speedup?: number
  /** Numeric extras forwarded from the evaluator (`native_metrics`). */
  metrics?: Record<string, number>
  /** The evaluator flagged a replay / reward-hack detector. */
  rewardHack?: boolean
  /** Evaluator-reported error message when the run failed. */
  error?: string
  /** Call logged but result not yet — evaluation in flight. */
  pending?: boolean
  /** This evaluation was later selected by a finalize call. */
  finalized?: boolean
  /**
   * Session-log seq of the finalize call that selected it — the latest one,
   * when several did. Present exactly when {@link WireIteration.finalized}
   * is, and the only thing that orders two picks in a run that finalized
   * twice (which `challengeFinalize` is built to cause).
   */
  finalizeSeq?: number
  /** Blocking build-gate findings forwarded from the evaluator. */
  blocking?: string[]
  /** Advisory build-gate findings forwarded from the evaluator. */
  advisory?: string[]
  /** Fields the evaluator explicitly named as not measured. */
  notMeasured?: string[]
  /** The evaluator itself failed — no verdict on the kernel exists. */
  evaluatorFailed?: boolean
  /** Workload subset requested on the call, when not a full evaluation. */
  workloadSubset?: number[]
  /** Artifact path passed to the evaluation call. */
  artifactPath?: string
  /** Structured artifact edits logged since the previous evaluation call. */
  changes?: WireChange[]
  /**
   * How the measurement entered the log. Absent = a registered/MCP tool
   * result (not forgeable by the agent). `'shell'` = a contract trailer line
   * parsed out of a shell tool's output — agent-relayed, so self-reported;
   * judge it with `command`. `'replay'` = the plugin re-executed the recorded
   * command itself at finalize (not agent-relayed).
   */
  channel?: 'shell' | 'replay'
  /** Command line that produced this point (shell/replay channels). */
  command?: string
}

/**
 * One logged `write`/`edit` tool call against the evaluated artifact,
 * attributed to the evaluation that followed it.
 */
export interface WireChange {
  /** Session-log seq of the change call. */
  seq: number
  /** Tool name as logged. */
  tool: string
  kind: 'write' | 'edit'
  /** Full file content for writes (possibly truncated). */
  content?: string
  /** Replaced text for edits (possibly truncated). */
  oldText?: string
  /** Replacement text for edits (possibly truncated). */
  newText?: string
  /** The edit had `replace_all` set. */
  replaceAll?: boolean
  /** Some text field was cut at the wire cap. */
  truncated?: boolean
}

/**
 * One `kernel_env` call — the environment the agent's EVALUATIONS run in.
 *
 * Deliberately agent-reported rather than probed by the plugin. The plugin
 * runs on the host that serves the panel, but the benchmark may execute on a
 * remote box (rt/ssh), a cloud runner, or a container — and even on one
 * machine the user may have ruled a device out ("CPU only", a pinned
 * `CUDA_VISIBLE_DEVICES`). Only the agent knows where it decided to measure
 * and under which constraint, so a plugin-side probe would confidently
 * describe the wrong machine. `probe` keeps it checkable: it names the
 * commands the facts came from, the way `command` does for a measurement.
 */
export interface WireEnv {
  /** Session-log seq of the report. */
  seq: number
  /** Where evaluations execute, in the agent's own words. */
  location: string
  /** The compute device the timed runs actually use. */
  device: string
  /** Why this device — a user instruction or task constraint, when one applies. */
  constraint?: string
  /** Key toolchain versions (name → version), as the agent read them. */
  versions?: Record<string, string>
  /** Command(s) the facts above were read from. */
  probe?: string
  /** Anything else that qualifies the measurements (clock locking, sharing, …). */
  notes?: string
}

/** One `kernel_plan` call — the model's stated plan at that point. */
export interface WirePlan {
  /** Session-log seq of the plan call. */
  seq: number
  /** Loop phase, e.g. explore / tune / verify. */
  phase: string
  /** One-line description of the current approach. */
  approach: string
  /** Why this approach should be faster. */
  hypothesis?: string
  /** Immediate next action. */
  next?: string
}

/**
 * One kernel-loop message parsed back from the session log: a continuation
 * round or the final wrap-up. Durable — survives restarts and replays, unlike
 * the in-memory control state.
 */
export interface WireRound {
  /** Session-log seq of the delivered message. */
  seq: number
  /** 1-based continuation round (absent on wrap-up messages). */
  round?: number
  /** Completed evaluations at delivery. */
  evalsUsed?: number
  /** Armed budget at delivery. */
  budget?: number
  /**
   * Supervisor outcome for the round: `'ok'` when it reviewed and approved,
   * the advice text when it objected, absent when no review ran.
   */
  review?: string
  /**
   * The supervisor's one-line observation when it approved — what that review
   * checked and saw. Absent on objections (the advice IS the record) and on
   * approvals from before the note was required.
   */
  reviewNote?: string
  /** This message was the wrap-up delivery (budget / no-progress ending). */
  wrapUp?: boolean
  /** This message was the closing audit after a finalized run. */
  audit?: boolean
  /**
   * This round overruled an early finalize: the agent declared the run
   * finished, the supervisor found headroom, and `review` carries the untried
   * directions it named.
   */
  challenge?: boolean
}

/** Loop + supervisor control state for the panel. */
export interface WireControl {
  /**
   * The run's current result, resolved by {@link runHeadline} — absent until
   * one eligible evaluation lands. Carried on the light control route so the
   * composer strip can show the number without fetching the whole series.
   */
  result?: {
    latencyMs: number
    /** Reported by that evaluation, else pooled over the run. */
    speedup?: number
    /** Whether this is the wrap-up pick rather than the running best. */
    finalized: boolean
  }
  loop: {
    /** Whether the kernel loop re-drives this session at turn settle. */
    armed: boolean
    /** Armed evaluation budget. */
    budget: number
    /** Continuations delivered so far. */
    round: number
    /** Completed evaluations at last projection. */
    evalsDone: number
    /** Completed optimization evaluations beyond the armed budget. */
    evalsOverBudget: number
    /** Output language frozen when this loop run was armed from the panel. */
    outputLanguage?: RunLanguage
    /** Why the loop disarmed, when it did. */
    stopReason?: string
    /** Whether the loop machinery is composed (commands/llm present). */
    available: boolean
    /** Budget an argument-less arm would use (config `loop.defaultBudget`). */
    defaultBudget: number
  }
  supervisor: {
    /** Whether reviews run at continuation points (per-session toggle). */
    enabled: boolean
    /** Whether any supervisor route is in effect (config or session override). */
    configured: boolean
    /**
     * The plugin-config default route, when one is configured — what the
     * picker's "default" option resolves to, shown even while a session
     * override is active.
     */
    configRoute?: { provider: string; model: string; reasoningEffort?: string }
    /** The route reviews would use, and where it came from. */
    effective?: {
      provider: string
      model: string
      /** Explicit review effort, absent when the model/provider default applies. */
      reasoningEffort?: string
      /** `'session'` = panel/command override for this session; `'config'` = plugin config. */
      source: 'session' | 'config'
    }
    /** Last delivered advice, for display. */
    lastAdvice?: string
  }
}

/** Languages the Web client can freeze for one optimization run. */
export type RunLanguage = 'zh' | 'en'

/** Provider/model catalog served for the panel's supervisor picker. */
export interface WireModels {
  providers: {
    /** Provider route key (as accepted by the supervisor config). */
    id: string
    /** Display name. */
    name: string
    /** Models on that route; empty when discovery failed or none published. */
    models: { id: string; name: string }[]
  }[]
}

/** Adapter-owned reasoning choices for one exact supervisor route. */
export interface WireModelInfo {
  provider: string
  id: string
  name: string
  reasoning?: {
    efforts: { id: string; name: string; description?: string }[]
    defaultEffort?: string
  }
}

/** Series payload served at the series route for one session. */
export interface WireSeries {
  /** Session the series was projected from. */
  sessionId: string
  /** Server time of the projection (ms epoch). */
  updatedAt: number
  /** Evaluations in log order. */
  iterations: WireIteration[]
  /** Plan reports in log order (latest last). */
  plans: WirePlan[]
  /** Evaluation-environment reports in log order (latest wins on the panel). */
  envs: WireEnv[]
  /** seqs of profile-tool calls (event markers between iterations). */
  profileSeqs: number[]
  /**
   * One entry per contract line that arrived through a channel no branch of
   * the projection collects. Non-empty means real evaluations ran where the
   * panel and the budget gate cannot see them — the shape of failure that
   * background jobs caused before they were collected, kept as the net for
   * whatever channel is unaccounted for next.
   */
  uncollectedSeqs: number[]
  /** Kernel-loop continuation/wrap-up messages in log order. */
  rounds: WireRound[]
  /** Index into `iterations` of the best honest measurement, if any. */
  bestIndex: number | null
  /** Loop/supervisor state when the kernel loop is present for this session. */
  control?: WireControl
}

/**
 * Whether two logged paths plausibly address the same file (exact, or one is
 * the other's path suffix). Shared protocol helper: the projection matches
 * changes/finalizes with it and the panel matches replay coverage.
 */
export function samePath(a: string, b: string): boolean {
  return a === b || a.endsWith(`/${b}`) || b.endsWith(`/${a}`)
}

/**
 * Whether an evaluation may count as the run's best.
 *
 * Four conditions, all disqualifying: a wrong answer, a flagged reward hack,
 * a failed evaluation, and a point that was never timed. Stated here because
 * three places now decide it — the projection picking `bestIndex`, the same
 * projection resolving which measurement of a finalized artifact is the
 * wrap-up pick, and the headline choosing its result. A private copy
 * would eventually let the panel draw a best no evaluation ever reached.
 *
 * Narrows `latencyMs`, so a caller that passes the guard can compare
 * latencies without re-testing the field it just tested.
 * @param point - one projected evaluation.
 * @returns whether it is a result the run can claim.
 */
export function eligibleBest(point: WireIteration): point is WireIteration & { latencyMs: number } {
  return point.correct === true && point.rewardHack !== true
    && point.error === undefined
    // Positive, not merely present. A zero or negative latency is not a very
    // fast kernel, it is a broken measurement — and it propagates: the axis
    // maps 1/latency, so zero puts a point at infinity and takes the whole
    // y domain to NaN with it, and the headline divides the reference by it.
    // The contract accepts any finite number, so this is reachable from a
    // user's own evaluator, not just from a bug in ours.
    && point.latencyMs !== undefined && point.latencyMs > 0
}

/** What the panel's headline states, and what it must not leave out. */
export interface RunHeadline {
  /** The result the run stands behind; absent until one eligible point lands. */
  claim?: WireIteration
  /** Whether {@link RunHeadline.claim} is a finalize pick rather than the running best. */
  finalized: boolean
  /**
   * The fastest eligible measurement, when it is NOT the claim — the run
   * measured something quicker than the version it shipped.
   */
  fasterMeasured?: WireIteration
  /**
   * The run's latest finalize pick when it is one the run cannot claim: a
   * wrong answer, a flagged reward hack, a failed evaluation, or a version
   * that was never timed. Present only in that case, and never as the claim.
   */
  unclaimablePick?: WireIteration
  /** Evaluations that returned a verdict the run cannot claim. */
  rejected: number
}

/**
 * Resolve the one number the panel prints largest.
 *
 * The claim is the FINALIZE PICK when the run made one, not the fastest row.
 * Those two genuinely differ: `bestIndex` ranges over every artifact the run
 * ever timed, while the wrap-up pick is the best measurement of the artifact the
 * agent actually chose — so a run that explored `experiments/fast.py` and
 * shipped `kernel.py` has a fastest row it is not claiming. Headlining the
 * fastest row there would advertise a number nobody can install.
 *
 * When they differ, {@link RunHeadline.fasterMeasured} carries the other one
 * so the panel can print both. Losing that would be the more attractive bug:
 * a headline that quietly reports the shipped version while a faster row sits
 * in the table reads, to anyone who scrolls, like the panel got caught.
 * @param iterations - the projected evaluations.
 * @param bestIndex - the projection's own best-point index.
 * @returns the headline model.
 */
export function runHeadline(
  iterations: readonly WireIteration[],
  bestIndex: number | null,
): RunHeadline {
  const best = bestIndex === null ? undefined : iterations[bestIndex]
  // The replay row re-measures the pick rather than being a pick of its own.
  const picks = iterations.filter(p => p.finalized === true && p.channel !== 'replay')
  // The LATEST pick, ordered by the finalize call that made it rather than by
  // where its evaluation sits in the log — a second finalize routinely names
  // an earlier evaluation, so log position ranks the two picks wrong. And
  // only among picks the run can actually stand behind: `evaluation_id`
  // finalize marks whatever id it was given, so a run that finalized on a
  // failed evaluation would otherwise put that failure under the word
  // "passed" in the largest type on the panel.
  const claimable = picks.filter(eligibleBest)
  const final = claimable.reduce<WireIteration | undefined>(
    (latest, p) => (latest === undefined || (p.finalizeSeq ?? 0) > (latest.finalizeSeq ?? 0) ? p : latest),
    undefined,
  )
  // A run that finalized, but on nothing it can claim. Falling back to the
  // running best is right — that number IS verified — but silently doing so
  // would hide the more interesting fact, so the pick comes back too.
  const unclaimable = final === undefined && picks.length > 0
    ? picks.reduce((latest, p) => ((p.finalizeSeq ?? 0) > (latest.finalizeSeq ?? 0) ? p : latest))
    : undefined
  const claim = final ?? best
  const rejected = iterations.filter(p => p.pending !== true && !eligibleBest(p)).length
  return {
    ...(claim !== undefined ? { claim } : {}),
    finalized: final !== undefined,
    ...(best !== undefined && claim !== undefined && best !== claim
      && best.latencyMs !== undefined && claim.latencyMs !== undefined
      && best.latencyMs < claim.latencyMs
      ? { fasterMeasured: best }
      : {}),
    ...(unclaimable !== undefined ? { unclaimablePick: unclaimable } : {}),
    rejected,
  }
}

/**
 * The reference latency each evaluation actually divided by, recovered as
 * `latency × speedup`. A frozen denominator repeats one value; an evaluator
 * that re-times its reference per evaluation returns a slightly different one
 * each time, and one that re-times it per CONTAINER — the normal shape of
 * remote evaluation, where the cache file dies with the container — can return
 * a very different one. Shared protocol helper: the chart pools these into the
 * axis, and the drift check below reads their spread.
 */
export function impliedReferences(iterations: readonly WireIteration[]): number[] {
  const out: number[] = []
  for (const point of iterations) {
    const { latencyMs, speedup } = point
    if (latencyMs === undefined || latencyMs <= 0) continue
    if (speedup === undefined || speedup <= 0) continue
    out.push(latencyMs * speedup)
  }
  return out
}

/**
 * Widest denominator disagreement in a run, as a ratio of the largest implied
 * reference to the smallest — reported only once it is wide enough to change a
 * reading, so a quiet run says nothing.
 *
 * The threshold sits between two measured shapes. Re-timing an unchanged
 * reference on one settled A100 spread it 2.14 / 2.06 / 2.03 ms — 5.4% — which
 * moves a speedup's last digit and nothing else. Re-timing it once per
 * container across 13 containers of one remote run spread it 2.03 → 3.11 ms —
 * 53% — and there the same unchanged kernel reported ×35.5 and ×53.2, which is
 * larger than most late-run improvements and reads as one. 15% is about three
 * times ordinary jitter and far below a reading that misleads.
 *
 * Four ratios are the floor for saying anything: below that a spread is one
 * unlucky measurement rather than a pattern, and the run has too few numbers
 * to compare anyway.
 */
export const REFERENCE_DRIFT_RATIO = 1.15
const REFERENCE_DRIFT_MIN_POINTS = 4

export interface ReferenceDrift {
  /** Smallest and largest reference latency (ms) any evaluation implied. */
  min: number
  max: number
  /** `max / min` — 1.53 means the widest pair disagreed by 53%. */
  ratio: number
  /** How many evaluations reported a ratio at all. */
  count: number
}

export function referenceDrift(iterations: readonly WireIteration[]): ReferenceDrift | undefined {
  const implied = impliedReferences(iterations)
  if (implied.length < REFERENCE_DRIFT_MIN_POINTS) return undefined
  let min = implied[0] as number
  let max = min
  for (const value of implied) {
    if (value < min) min = value
    if (value > max) max = value
  }
  const ratio = max / min
  return ratio >= REFERENCE_DRIFT_RATIO ? { min, max, ratio, count: implied.length } : undefined
}

/**
 * Index into `rounds` where the latest loop run begins. Every arm resets the
 * continuation counter, so a round number that does not increase past its
 * predecessor's opens a new run; wrap-up messages (no round number) stay with
 * the run they close. Shared protocol helper: the panel scopes its
 * supervision card to the current run with it, while the full history stays
 * on the wire.
 */
export function latestRunStart(rounds: readonly WireRound[]): number {
  let start = 0
  let prev: number | undefined
  for (let i = 0; i < rounds.length; i += 1) {
    const num = rounds[i]?.round
    if (num === undefined) continue
    if (prev !== undefined && num <= prev) start = i
    prev = num
  }
  return start
}

/**
 * Whether the iteration logged at `seq` belongs to a wrap-up phase: the
 * governing loop message above it is a wrap-up delivery or the closing audit,
 * so the evaluation is finalize verification or audit correction, not
 * budgeted optimization work. Only a numbered continuation (a new drive)
 * exits the phase. Shared protocol helper: the panel splits its chips and
 * badges rows with it, keeping "N iterations" aligned with the armed budget.
 */
export function inWrapUpPhase(rounds: readonly WireRound[], seq: number): boolean {
  let phase = false
  for (const round of rounds) {
    if (round.seq > seq) break
    if (round.wrapUp === true || round.audit === true) phase = true
    else if (round.round !== undefined) phase = false
  }
  return phase
}

/** One evaluation row's relationship to the active optimization budget. */
export type EvaluationPhase = 'optimization' | 'over-budget' | 'wrap-up'

/**
 * Classify evaluations without pretending turn-boundary overshoot is
 * budgeted work. Wrap-up/replay rows never consume optimization budget;
 * among the remaining completed rows, only the first `budget` do.
 * @param iterations - evaluations in log order.
 * @param rounds - loop messages that delimit wrap-up phases.
 * @param budget - latest armed optimization-evaluation budget; zero means unknown.
 * @returns one phase per evaluation, in input order.
 */
export function evaluationPhases(
  iterations: readonly WireIteration[],
  rounds: readonly WireRound[],
  budget: number,
): EvaluationPhase[] {
  let completed = 0
  return iterations.map((point) => {
    if (point.channel === 'replay' || inWrapUpPhase(rounds, point.seq)) return 'wrap-up'
    if (point.pending !== true) completed += 1
    return budget > 0 && completed > budget ? 'over-budget' : 'optimization'
  })
}

/**
 * Whether the log shows a loop run that never ended: the last loop message is
 * a continuation (not a wrap-up or closing audit) and nothing was finalized
 * after it. Loop state lives in memory, so a host restart takes an armed run
 * with it — no drive, no wrap-up, no finalize, and the panel forgets it was
 * ever armed. The log still remembers, and the human deserves to be told the
 * run was cut off rather than silently handed an unfinished curve. A manual
 * stop leaves the same trace, so the caption names both possibilities.
 * @param rounds - loop messages in log order.
 * @param iterations - evaluations in log order.
 * @returns whether the newest run ended without any closing record.
 */
export function unfinishedRun(
  rounds: readonly WireRound[],
  iterations: readonly WireIteration[],
): boolean {
  const last = rounds[rounds.length - 1]
  if (last === undefined || last.wrapUp === true || last.audit === true) return false
  return !iterations.some(p => p.finalized === true && p.seq > last.seq)
}

/**
 * Id of the bundled「算子优化模式」agent preset the Node half seeds into the
 * user preset root. Shared constant: sessions composed from this preset id
 * always show the evaluation tab (before any evaluation lands).
 */
export const PRESET_ID = 'kernel-opt'

/** Route the Node half serves and the panel polls (query: `?sessionId=`). */
export const SERIES_PATH = '/plugins/kernel-opt/series'

/**
 * Control route. POST `{ sessionId, action, budget?, outputLanguage?,
 * provider?, model?, reasoningEffort? }`
 * with action one of `loop-arm` / `loop-stop` / `supervise-on` /
 * `supervise-off` / `supervise-use` (both provider+model set the session
 * override; both empty resets to config). GET `?sessionId=` returns the same
 * fresh {@link WireControl} without acting — the lightweight poll for the
 * chat-side loop affordances. The slash commands remain the scriptable twin
 * of the same state.
 */
export const CONTROL_PATH = '/plugins/kernel-opt/control'

/** Models route (GET): the {@link WireModels} catalog for the picker. */
export const MODELS_PATH = '/plugins/kernel-opt/models'

/**
 * Prefix of the evaluation contract trailer line. Any evaluation pipeline —
 * whatever it does internally — participates in the panel by printing one
 * line to stdout:
 *
 * `KERNEL_EVAL={"artifact":"solution/k.py","latency_ms":1.23,"correct":true}`
 *
 * Required: `artifact` (which file this measures) and `correct`; `latency_ms`
 * whenever the run was timed. Optional: `compiled`, `error`, `native_metrics`
 * (numeric map; `speedup`/`ref_runtime_ms` feed the speedup column),
 * `reward_hack_detected`, `workload_indices`. One line per evaluation. This is
 * a public contract — published scripts print it, so it must never change.
 */
export const EVAL_TRAILER_PREFIX = 'KERNEL_EVAL='

/**
 * Line the Node half writes into a `kernel_finalize` tool result naming the
 * command it replayed; the projection reads it back as the replay point's
 * provenance.
 */
export const REPLAY_LINE_PREFIX = '[replay] '

/** First-line prefix of a continuation message (`round N` follows). */
export const LOOP_LINE_PREFIX = '[kernel-loop round '
/** First-line prefix of the wrap-up message. */
export const WRAPUP_LINE_PREFIX = '[kernel-loop wrap-up]'
/** First-line prefix of the closing-audit message after a finalized run. */
export const AUDIT_LINE_PREFIX = '[kernel-loop final review]'
/** Line opening the wrap-up's closing instructions (ends a review block). */
export const WRAPUP_CLOSE_LINE = 'The kernel loop is ending'
/** Line opening the audit's closing instructions (ends a review block). */
export const AUDIT_CLOSE_LINE = 'Address the findings'
/**
 * Sentence marking a continuation as an overruled finalize (the run was
 * declared finished and the supervisor found headroom). Sits inside the
 * challenge's trailer, so the projection flags the round from the text alone.
 */
export const CHALLENGE_LINE = 'the run is NOT over'
/** Header line introducing a supervisor advice block. */
export const REVIEW_HEADER = 'Supervisor review (advisory, from the second model):'
/** Whole line recording that the supervisor reviewed and approved. */
export const REVIEW_OK_LINE = 'Supervisor review: OK.'
/**
 * Start of the fixed trailer paragraph (terminates the advice block). The
 * anchor is task-neutral: the sentence completing it adapts to whether the
 * session already carries a task (see `continuationText`).
 */
export const CONTINUE_TRAILER = 'Continue the kernel-optimization run'
